-- World DB. Removes doubled Riverpaw gnoll spawns in Elwynn Forest from the AnoCore spawn restore
-- (2026_11_02_29), which overlaid a second camp layout on top of the baseline one in both Riverpaw camps.
--
-- Hogger Hill / Forest's Edge (zone ~27,90, world ~-10000,+600): baseline has 45 spawn points; the
-- restore added 15 pooled spots (Runt|Outrunner pairs, pools 1700015 and 1700036-1700049) plus 4
-- unpooled singles. 13 of the pools sit <=25 y of baseline spawns and are removed; pools 1700015
-- (-10045,575.6, 31.9 y) and 1700041 (-9996.1,603.1, 27.9 y) are kept as legitimate edge gap-fills.
--
-- Southeast camp / Three Corners (world ~-8900,-800): all 14 restored pools (1700050-1700063) sit
-- 5-16 y of baseline spawns; all removed.
--
-- The 4 unpooled AnoCore singles land 5-17 y from a baseline spawn of the SAME entry and are removed:
--   86614 Riverpaw Gnoll (5.2 y from baseline 20086614)
--   86782 Riverpaw Gnoll (5.9 y from baseline 20086782)
--   86784 Riverpaw Gnoll (16.8 y from baseline 20086785)
--   89604 Riverpaw Mongrel (6.1 y from baseline 20089604)
--
-- Also removes baseline pool 1086785 at (-9730.3,1451.5): pools 1086784 and 1086785 occupy the exact
-- same point, so two gnolls spawn stacked. Pool 1086784 (members 20086784 Gnoll / 25347136 Scout)
-- is kept; pool 1086785 (members 20086785 Gnoll / 25347140 Scout) is removed.
--
-- None of the removed spawns have waypoints, formations, scripts, events, spawn_group or addon rows.
-- Safe to run again.
--
-- Removed pools:  1700036,1700037,1700038,1700039,1700040,1700042,1700043,1700044,1700045,1700046,
--                 1700047,1700048,1700049 (Hogger Hill), 1700050-1700063 (southeast camp), 1086785.
-- Kept pools:     1700015 (-10045.1,575.6), 1700041 (-9996.1,603.1), 1086784.
CREATE TABLE IF NOT EXISTS bak_0009_creature AS SELECT * FROM creature WHERE guid IN (86614,86782,86784,89604,20086785,25347140,80493,80503,80507,80509,80511,80527,80528,80530,80532,80538,80545,80546,80551,81112,81113,81114,81115,81121,81124,81126,81128,81129,81136,81139,81146,81154,81338,9101128,9101132,9101136,9101138,9101139,9101153,9101154,9101155,9101156,9101162,9101166,9101167,9101168,9101178,9101179,9101180,9101181,9101187,9101188,9101190,9101191,9101192,9101198,9101201,9101208,9101214,9101293);
